/**
* Load the repository's configured mapping of teams <> labels.
*
* @return Mapping of teams <> labels.
*/
async function loadTeamAssignments() {
	const teamAssignmentsString = getInput("labels_team_assignments");
	if (!teamAssignmentsString) {
		debug(`triage-issues > update-board: No mapping of teams <> labels provided. Cannot automatically assign an issue to a specific team on the board. Aborting.`);
		return {};
	}
	const teamAssignments = JSON.parse(teamAssignmentsString);
	if (!teamAssignments || !Object.keys(teamAssignments).length || !Object.values(teamAssignments).some((assignment) => assignment.team) || !Object.values(teamAssignments).some((assignment) => assignment.labels)) {
		debug(`triage-issues > update-board: Invalid mapping of teams <> labels provided. Cannot automatically assign an issue to a specific team on the board. Aborting.`);
		return {};
	}
	return teamAssignments;
}
/**
* Check if an issue has a label that matches a team.
* If so, assign the issue to that team on the project board.
* If not, do nothing.
* It could be an existing label,
* or it could be that it's being added as part of the event that triggers this action.
*
* @param octokit        - Initialized Octokit REST client.
* @param payload        - Issue event payload.
* @param projectInfo    - Info about our project board.
* @param projectItemId  - The ID of the project item.
* @param isBug          - Is the issue a bug?
* @param priorityLabels - Array of priority labels.
* @return The new project item id.
*/
async function assignTeam(octokit, payload, projectInfo, projectItemId, isBug, priorityLabels) {
	const { action, issue: { number }, repository: { owner, name } } = payload;
	const label = "label" in payload ? payload.label : void 0;
	const ownerLogin = owner.login;
	const teamAssignments = await loadTeamAssignments();
	if (!Object.keys(teamAssignments).length) {
		debug(`triage-issues > update-board: No mapping of teams <> labels provided. Cannot automatically assign an issue to a specific team on the board. Aborting.`);
		return projectItemId;
	}
	const labels = await getLabels(octokit, ownerLogin, name, number);
	if ("labeled" === action && label?.name) labels.push(label.name);
	const [featureName, { team, slack_id, board_id } = {}] = Object.entries(teamAssignments).find(([, assignment]) => labels.some((mappedLabel) => assignment.labels.includes(mappedLabel))) || [];
	if (!team) {
		debug(`triage-issues > update-board: Issue #${number} does not have a label that matches a team. Aborting.`);
		return projectItemId;
	}
	debug(`triage-issues > update-board: Assigning the "${team}" team for this project item, issue #${number}.`);
	projectItemId = await setTeamField(octokit, projectInfo, projectItemId, team);
	if (slack_id && priorityLabels.length > 0 && (priorityLabels.includes("[Pri] BLOCKER") || priorityLabels.includes("[Pri] High")) && isBug) {
		debug(`triage-issues > update-board: Issue #${number} has the following priority labels: ${priorityLabels.join(", ")}. The ${team} team is interested in getting Slack updates for important issues. Let's notify them.`);
		await notifyImportantIssues(octokit, payload, slack_id, "devs");
	}
	if (board_id) {
		debug(`triage-issues > update-board: Issue #${number} is associated with the "${featureName}" feature, and the ${team} team has a dedicated project board for this feature. Let's add the issue to that board.`);
		const featureProjectInfo = await getProjectDetails(octokit, board_id);
		if (Object.keys(featureProjectInfo).length === 0 || !featureProjectInfo.projectNodeId) {
			setFailed(`triage-issues > update-board: we cannot fetch info about the project board associated to the "${featureName}" feature. Aborting task.`);
			return projectItemId;
		}
		let featureIssueItemId = await getIssueProjectItemId(octokit, featureProjectInfo, name, number);
		if (!featureIssueItemId) {
			debug(`triage-issues > update-board: Issue #${number} is not on our project board. Let's add it.`);
			featureIssueItemId = await addIssueToBoard(payload, octokit, featureProjectInfo);
			if (!featureIssueItemId) {
				debug(`triage-issues > update-board: Failed to add issue to project board. Aborting.`);
				return projectItemId;
			}
		}
	}
	return projectItemId;
}
/**
* Automatically update specific columns in our common GitHub project board,
* to match labels applied to issues.
*
* @param payload        - Issue event payload.
* @param octokit        - Initialized Octokit REST client.
* @param issueType      - Type of the issue, defined by a "[Type]" label on the issue.
* @param priorityLabels - Array of Priority Labels matching this issue.
*/
async function updateBoard(payload, octokit, issueType, priorityLabels) {
	const { issue: { number }, repository: { owner, name } } = payload;
	const ownerLogin = owner.login;
	const isBug = issueType === "Bug";
	const projectToken = getInput("triage_projects_token");
	if (!projectToken) {
		debug(`triage-issues > update-board: Input triage_projects_token is required but missing. Aborting.`);
		return;
	}
	const projectBoardLink = getInput("project_board_url");
	if (!projectBoardLink) {
		debug(`triage-issues > update-board: No project board link provided. Cannot triage to a board. Aborting.`);
		return;
	}
	const projectOctokit = getOctokit(projectToken);
	const projectInfo = await getProjectDetails(projectOctokit, projectBoardLink);
	if (Object.keys(projectInfo).length === 0 || !projectInfo.projectNodeId) {
		debug(`triage-issues > update-board: we cannot fetch info about our project board. Aborting task.`);
		return;
	}
	let projectItemId = await getIssueProjectItemId(projectOctokit, projectInfo, name, number);
	if (!projectItemId && isBug) {
		debug(`triage-issues > update-board: Issue #${number} is not on our project board. Let's add it.`);
		projectItemId = await addIssueToBoard(payload, projectOctokit, projectInfo);
		if (projectItemId) {
			debug(`triage-issues > update-board: Setting the "Needs Triage" status for this project item, issue #${number}.`);
			projectItemId = await setStatusField(projectOctokit, projectInfo, projectItemId, "Needs Triage");
		} else debug(`triage-issues > update-board: Failed to add issue to project board.`);
	}
	if (issueType && projectInfo.type && projectItemId) {
		debug(`triage-issues > update-board: Issue #${number} has a type label set, ${issueType}. Let's ensure the Type field of the project board matches that.`);
		if ([
			"Bug",
			"Enhancement",
			"Task"
		].includes(issueType)) projectItemId = await setTypeField(projectOctokit, projectInfo, projectItemId, issueType);
	}
	if (priorityLabels.length > 0 && projectInfo.priority && projectItemId) {
		debug(`triage-issues > update-board: Issue #${number} has the following priority labels: ${priorityLabels.join(", ")}`);
		const priorityText = priorityLabels[0].replace(/^\[Pri\]\s*/, "");
		debug(`triage-issues > update-board: Setting the "${priorityText}" priority for this project item, issue #${number}.`);
		projectItemId = await setPriorityField(projectOctokit, projectInfo, projectItemId, priorityText);
	}
	const labels = await getLabels(octokit, ownerLogin, name, number);
	if (labels.includes("Triaged") && projectItemId) if (labels.some((label) => label.match(/^\[Status\] Needs (3rd Party|Core) Fix$/))) {
		debug(`triage-issues > update-board: Issue #${number} needs a third-party fix. Setting the "Needs Core/3rd Party Fix" status for this project item.`);
		await setStatusField(projectOctokit, projectInfo, projectItemId, "Needs Core/3rd Party Fix");
	} else {
		debug(`triage-issues > update-board: Setting the "Triaged" status for this project item, issue #${number}.`);
		await setStatusField(projectOctokit, projectInfo, projectItemId, "Triaged");
	}
	if (projectItemId) projectItemId = await assignTeam(projectOctokit, payload, projectInfo, projectItemId, isBug, priorityLabels);
}
//#endregion
//#region src/tasks/triage-issues/index.ts
/**
* If we could not add labels via OpenAI, let's add a comment to ask the issue author to add their own labels.
*
* We only want to do this if the author can actually add labels to the issue, i.e. if they're part of the organization.
*
* @param octokit     - Initialized Octokit REST client.
* @param ownerLogin  - Owner of the repository.
* @param authorLogin - Author of the issue.
* @param repo        - Repository name.
* @param issueNumber - Issue number.
*
* @return Promise resolving when the comment is added.
*/
async function addCommentAskLabels(octokit, ownerLogin, authorLogin, repo, issueNumber) {
	debug(`triage-issues > auto-label: Issue #${issueNumber} created by ${authorLogin}, lacking label suggestions by OpenAI. Asking the author to add labels.`);
	try {
		await octokit.rest.orgs.checkMembershipForUser({
			org: ownerLogin,
			username: authorLogin
		});
	} catch {
		debug(`triage-issues > auto-label: Author ${authorLogin} is not an org member. Skipping comment.`);
		return;
	}
	await octokit.rest.issues.createComment({
		owner: ownerLogin,
		repo,
		body: `This issue could use some more labels, to help prioritize and categorize our work. Could you please add at least a \`[Feature]\`, a \`[Pri]\`, and a Type label?
`,
		issue_number: issueNumber
	});
}
/**
* Automatically add labels to issues, and send Slack notifications.
*
* This task can send 2 different types of Slack notifications:
* - If an issue is determined as High or Blocker priority,
* - If no priority is determined.
*
* @param payload - Issue event payload.
* @param octokit - Initialized Octokit REST client.
*/
async function triageIssues(payload, octokit) {
	const { action, issue, repository } = payload;
	const { user: { login: authorLogin }, number, body, state } = issue;
	const { owner, name, full_name } = repository;
	const ownerLogin = owner.login;
	if ("open" !== state) {
		debug(`triage-issues: Issue #${number} is not open. No need to triage it.`);
		return;
	}
	const { labels: priorityLabels, inferred } = await getIssuePriority(payload, octokit);
	const issueType = await getIssueType(octokit, ownerLogin, name, number);
	const isBug = issueType === "Bug";
	const qualityChannel = getInput("slack_quality_channel");
	if (action === "opened" || action === "reopened") {
		const impactedPlugins = findPlugins(body ?? "");
		if (impactedPlugins.length > 0) {
			debug(`triage-issues: Adding plugin labels to issue #${number}`);
			const pluginLabels = impactedPlugins.map((plugin) => `[Plugin] ${plugin}`);
			await octokit.rest.issues.addLabels({
				owner: ownerLogin,
				repo: name,
				issue_number: number,
				labels: pluginLabels
			});
		}
		const impactedPlatforms = findPlatforms(body ?? "");
		if (impactedPlatforms.length > 0) {
			debug(`triage-issues: Adding platform labels to issue #${number}`);
			const platformLabels = impactedPlatforms.map((platform) => `[Platform] ${platform}`);
			await octokit.rest.issues.addLabels({
				owner: ownerLogin,
				repo: name,
				issue_number: number,
				labels: platformLabels
			});
		}
		if (priorityLabels.length === 1 && isBug && inferred) {
			const inferredPriority = priorityLabels[0];
			debug(`triage-issues: Adding ${inferredPriority} label to issue #${number}`);
			await octokit.rest.issues.addLabels({
				owner: ownerLogin,
				repo: name,
				issue_number: number,
				labels: [inferredPriority]
			});
			if (inferredPriority === "[Pri] TBD" && full_name === "Automattic/wp-calypso" && qualityChannel) {
				debug(`triage-issues: #${number} doesn't have a Priority set. Sending in Slack message to the triage team.`);
				const message = "New bug missing priority. Please do a priority assessment.";
				await sendSlackMessage(message, qualityChannel, payload, formatSlackMessage(payload, qualityChannel, message));
			}
		}
		if (getInput("ai_labeling_enabled") === "true") {
			const issueLabels = await aiLabeling(payload, octokit);
			const hasTypeLabel = issueLabels.some((label) => label.startsWith("[Type]")) || issueLabels.some((label) => TYPE_LABELS_WITHOUT_PREFIX.includes(label));
			const hasPriorityLabel = issueLabels.some((label) => /^\[Pri/.test(label));
			const hasFeatureLabel = issueLabels.some((label) => /^\[[^\]]*Feature/.test(label));
			if (!hasTypeLabel || !hasPriorityLabel || !hasFeatureLabel) await addCommentAskLabels(octokit, ownerLogin, authorLogin, name, number);
		}
	}
	await updateBoard(payload, octokit, issueType, priorityLabels);
	if (isBug && qualityChannel && priorityLabels.length > 0 && (priorityLabels.includes("[Pri] BLOCKER") || priorityLabels.includes("[Pri] High"))) await notifyImportantIssues(octokit, payload, qualityChannel, "product-ambassadors");
}
//#endregion
//#region src/utils/if-not-closed.ts
/**
* Higher-order function which executes and returns the result of the given
* handler only if the PR is not currently closed.
*
* @param handler - Original task.
* @return Enhanced task.
*/
function ifNotClosed(handler) {
	const newHandler = (payload, octokit) => {
		if (payload.pull_request.state !== "closed") return handler(payload, octokit);
		debug(`main: Skipping ${handler.name} because the PR is closed.`);
	};
	Object.defineProperty(newHandler, "name", { value: handler.name });
	return newHandler;
}
//#endregion
//#region src/utils/if-not-fork.ts
/**
* Higher-order function which executes and returns the result of the given
* handler only if the enhanced function is called with a payload indicating a
* pull request event which did not originate from a forked repository.
*
* @param handler - Original task.
* @return Enhanced task.
*/
function ifNotFork(handler) {
	const newHandler = (payload, octokit) => {
		if (payload.pull_request.head.repo?.full_name === payload.pull_request.base.repo?.full_name) return handler(payload, octokit);
		debug(`main: Skipping ${handler.name} because we are in a fork.`);
	};
	Object.defineProperty(newHandler, "name", { value: handler.name });
	return newHandler;
}
